import AppKit
import ApplicationServices
import Carbon
import CoreGraphics

extension PasteTyper {
    /// NSPasteboard.general, or another pasteboard (tests use one of their own).
    public final class SystemPasteboard: Pasteboard {
        /// Written with the text, so clipboard managers leave it out (nspasteboard.org): it's only there for a moment,
        /// it may be private, and it wasn't copied by you.
        static let markers = [
            "org.nspasteboard.TransientType", "org.nspasteboard.ConcealedType", "org.nspasteboard.AutoGeneratedType",
        ]

        private let pasteboard: NSPasteboard

        public init(_ pasteboard: NSPasteboard = .general) {
            self.pasteboard = pasteboard
        }

        public var changeCount: Int { pasteboard.changeCount }

        /// Every item, each with every type whose data can be read; a type that can't (a promise its app no longer
        /// keeps) is skipped, as on Windows.
        public func save() -> Contents? {
            var items: [[Contents.Representation]] = []
            for item in pasteboard.pasteboardItems ?? [] {
                let representations = item.types.compactMap { type in
                    item.data(forType: type).map { Contents.Representation(type: type.rawValue, data: $0) }
                }

                if !representations.isEmpty {
                    items.append(representations)
                }
            }

            return items.isEmpty ? nil : Contents(items: items)
        }

        /// The text and the markers, for this Mac only: Universal Clipboard doesn't offer it to your other devices (as
        /// Windows keeps it from the cloud clipboard).
        public func write(_ text: String) throws -> Int {
            _ = pasteboard.prepareForNewContents(with: .currentHostOnly)
            let item = NSPasteboardItem()
            _ = item.setString(text, forType: .string)
            for marker in Self.markers {
                _ = item.setData(Data(), forType: NSPasteboard.PasteboardType(marker))
            }

            guard pasteboard.writeObjects([item]) else { throw Failure.pasteboardUnavailable }
            return pasteboard.changeCount
        }

        public func restore(_ contents: Contents?) {
            _ = pasteboard.prepareForNewContents(with: contents?.isConcealed == true ? .currentHostOnly : [])
            guard let contents else { return }
            let items = contents.items.map { representations in
                let item = NSPasteboardItem()
                for representation in representations {
                    _ = item.setData(representation.data, forType: NSPasteboard.PasteboardType(representation.type))
                }

                return item
            }

            _ = pasteboard.writeObjects(items)
        }
    }

    /// The keyboard: the modifier keys held now, and keys sent with CGEvent, which needs the Accessibility permission.
    /// ⌘V is the key that types "v" with ⌘ in the keyboard layout in use (Dvorak's is QWERTY's "."), as Windows' Ctrl+V
    /// is the V key of the layout in use.
    public final class SystemKeys: Keys, @unchecked Sendable {
        private let lock = NSLock()
        private var pasteKey = CGKeyCode(kVK_ANSI_V)
        private var observer: NSObjectProtocol?

        /// Text Input Sources answers on the main thread only, so the paste key is found there, now or as soon as the
        /// main thread is free, and again whenever the keyboard layout changes.
        public init() {
            if Thread.isMainThread {
                updatePasteKey()
            } else {
                DispatchQueue.main.async { [weak self] in self?.updatePasteKey() }
            }

            let changed = Notification.Name(kTISNotifySelectedKeyboardInputSourceChanged as String)
            let center = DistributedNotificationCenter.default()
            observer = center.addObserver(forName: changed, object: nil, queue: .main) { [weak self] _ in
                self?.updatePasteKey()
            }
        }

        deinit {
            if let observer {
                DistributedNotificationCenter.default().removeObserver(observer)
            }
        }

        public var heldModifiers: Modifiers {
            let flags = CGEventSource.flagsState(.combinedSessionState)
            var held: Modifiers = []
            if flags.contains(.maskCommand) { held.insert(.command) }
            if flags.contains(.maskAlternate) { held.insert(.option) }
            if flags.contains(.maskControl) { held.insert(.control) }
            if flags.contains(.maskShift) { held.insert(.shift) }
            if flags.contains(.maskSecondaryFn) { held.insert(.function) }
            return held
        }

        public var secureInput: Bool { IsSecureEventInputEnabled() }

        public var pasteChord: Chord {
            Chord(key: lock.withLock { pasteKey }, modifiers: .command)
        }

        /// Key down and up, with the chord's modifier flags only: nothing else held reaches the app (the typer waits
        /// for held keys to be let go first). Without the Accessibility permission macOS would drop them silently, so
        /// nothing goes out and `Failure.notAllowed` is thrown.
        public func post(_ chord: Chord) throws {
            guard AXIsProcessTrusted() else { throw Failure.notAllowed }
            let source = CGEventSource(stateID: .combinedSessionState)
            guard let down = CGEvent(keyboardEventSource: source, virtualKey: chord.key, keyDown: true),
                  let up = CGEvent(keyboardEventSource: source, virtualKey: chord.key, keyDown: false) else {
                throw Failure.keysUnavailable
            }

            let flags = Self.eventFlags(chord.modifiers)
            down.flags = flags
            up.flags = flags
            down.post(tap: .cgSessionEventTap)
            up.post(tap: .cgSessionEventTap)
        }

        /// The modifiers' flags, each with the left-hand key's own bit too (NX_DEVICELCMDKEYMASK and so on), as a real
        /// key press has: some apps look at those.
        static func eventFlags(_ modifiers: Modifiers) -> CGEventFlags {
            var flags: UInt64 = 0
            if modifiers.contains(.command) { flags |= CGEventFlags.maskCommand.rawValue | 0x08 }
            if modifiers.contains(.option) { flags |= CGEventFlags.maskAlternate.rawValue | 0x20 }
            if modifiers.contains(.control) { flags |= CGEventFlags.maskControl.rawValue | 0x01 }
            if modifiers.contains(.shift) { flags |= CGEventFlags.maskShift.rawValue | 0x02 }
            if modifiers.contains(.function) { flags |= CGEventFlags.maskSecondaryFn.rawValue }
            return CGEventFlags(rawValue: flags)
        }

        private func updatePasteKey() {
            let key = Self.keyCode(typing: "v") ?? CGKeyCode(kVK_ANSI_V)
            lock.withLock { pasteKey = key }
        }

        /// The key that types `character` with ⌘ held in the layout ⌘ shortcuts use: the current one, or for a
        /// non-Latin one (Russian, Greek…) the Latin layout that goes with it. Main thread only.
        static func keyCode(typing character: Character) -> CGKeyCode? {
            guard let source = TISCopyCurrentASCIICapableKeyboardLayoutInputSource()?.takeRetainedValue() else {
                return nil
            }

            return keyCode(typing: character, in: source)
        }

        /// The key that types `character` with ⌘ held in `layout` (with ⌘, "Dvorak – QWERTY ⌘" types QWERTY), found
        /// with UCKeyTranslate. Main thread only.
        static func keyCode(typing character: Character, in layout: TISInputSource) -> CGKeyCode? {
            guard character.utf16.count == 1, let unit = character.utf16.first,
                  let property = TISGetInputSourceProperty(layout, kTISPropertyUnicodeKeyLayoutData) else { return nil }
            let data = Unmanaged<CFData>.fromOpaque(property).takeUnretainedValue()
            guard let bytes = CFDataGetBytePtr(data) else { return nil }

            let command = UInt32((cmdKey >> 8) & 0xFF)
            let keyboard = UInt32(LMGetKbdType())
            let options = OptionBits(kUCKeyTranslateNoDeadKeysMask)
            return bytes.withMemoryRebound(to: UCKeyboardLayout.self, capacity: 1) { keys -> CGKeyCode? in
                for code in UInt16(0)..<128 {
                    var deadKeys: UInt32 = 0
                    var length = 0
                    var typed = [UniChar](repeating: 0, count: 4)
                    let status = UCKeyTranslate(
                        keys, code, UInt16(kUCKeyActionDown), command, keyboard, options, &deadKeys, typed.count,
                        &length, &typed)
                    if status == 0, length == 1, typed[0] == unit {
                        return CGKeyCode(code)
                    }
                }

                return nil
            }
        }
    }
}
